function sentencePageIntegrated(v){let a=engine.analyze(v.text,saved.filter(x=>x.id).map(x=>x.id)),evidence=new Map(),localSentence=(byForm.get(norm(a.sentence))||[]).find(item=>item.type_code==='sentence'),sourceTranslation=primaryEnglishGloss(localSentence),sentenceRequest=sentenceLearningRequest(a),sentenceDraft=learningAssist()?.get(sentenceRequest),referenceTranslations=referenceLanguages().map(language=>learningAssist()?.get(sentenceLearningRequest(a,language))?.translation).filter(Boolean),primaryFailure=autoLearningFailures.get(autoLearningKey(sentenceRequest)),fallbackTranslation=primaryFailure?'Translation is temporarily unavailable while online assistance is busy.':aiAssistanceEnabled()?'Preparing translation…':'Local translation unavailable while online learning assistance is off.';view={...v,analysis:a};[...a.expressions,...a.grammar].forEach(n=>(n.evidence||[]).forEach(i=>{let marks=evidence.get(i)||[];marks.push(n.type==='grammar_construction'?'grammar':'expression');evidence.set(i,marks)}));let unknown=a.unknownTokens.length,formFindings=(a.formAnalyses||[]).map(node=>`<button class="fact sentence-finding" data-object="${esc(node.objectId)}">${esc(node.label)}</button>`).join(''); shell(`<section class="page sentence-page"><button class="back" data-back>← Back</button><div class="type">Sentence learning</div><h1 class="sentence-title">${esc(a.sentence)}</h1><div class="translation-block"><span>English</span><p class="translation">${esc(sourceTranslation||sentenceDraft?.translation||fallbackTranslation)}</p>${referenceTranslations.map(translation=>chinese(translation)).join('')}</div><div class="insight sentence-local-reading"><div class="label">Local reading</div><p>${esc(sentenceReading(a))}</p>${formFindings?`<div class="sentence-findings">${formFindings}</div>`:''}</div><div class="section"><h2>Sentence breakdown</h2><div class="tokens sentence-tokens">${a.tokens.map((t,i)=>clickable(t.objectId||t.lemmaId,t.surface,`token sentence-token ${(evidence.get(i)||[]).join(' ')}`)).join(' ')}</div>${unknown?`<p class="section-copy">Still to explore locally: ${esc(a.unknownTokens.join(', '))}.</p>`:''}</div>${sentenceLearningActions(a)}${a.grammar.length?`<div class="section"><h2>Grammar, explained</h2><div class="teacher-guides">${a.grammar.map(teacherGuide).join('')}</div></div>`:''}${a.expressions.length?`<div class="section"><h2>Useful connections</h2><div class="collocations">${a.expressions.map(n=>clickable(n.objectId,n.label,'link-card expression-card')).join('')}</div></div>`:''}<div class="section"><h2>Learning opportunities</h2><p class="section-copy">${a.learning.reviewCandidateIds.length} objects recognised · ${a.expressions.length} expressions · ${a.grammar.length} learning guides.</p><div class="facts"><span class="fact">${a.learning.newObjectIds.length} new</span><span class="fact">${a.learning.savedObjectIds.length} saved</span><span class="fact">${a.learning.reviewCandidateIds.length} review candidates</span><span class="fact">${estimateLevel(a)}</span></div></div></section>`)}
function render(){if(view.type==='object')objectPage(view);else if(view.type==='sentence')sentencePageIntegrated(view);else if(view.type==='missing')missing(view);else if(view.type==='vocab')vocabulary();else if(view.type==='settings')settings();else home()}
function renderTarget(next){let preserveScroll=view.type==='object'&&next.type==='object'&&view.id===next.id,scrollY=preserveScroll?window.scrollY:0;if(next.type==='object')objectPage(next);else if(next.type==='sentence')sentencePageIntegrated(next);else if(next.type==='settings')settings();else if(next.type==='vocab')vocabulary();else if(next.type==='missing')missing(next);else home();if(preserveScroll)requestAnimationFrame(()=>window.scrollTo(0,scrollY))}
function go(next){if(!next)return;navigationStack.push({...view});renderTarget(next)}
app.innerHTML='<main class="main"><p class="empty">Loading local knowledge graph…</p></main>';loadWordbank();
