/* Personal Learning Layer UI adapters. The graph stays read-only; these records
   only hold learner intent, organisation, and private review history. */
function personalItemsForCollection(collectionId){return personalLearning()?.itemsForCollection?.(collectionId)||saved}
function personalItemOpenControl(item){return item.targetObjectId?`<button data-personal-open="${esc(item.id)}"><strong>${esc(item.title)}</strong><span>${esc(item.detail)}</span></button>`:item.sourceContext?.sentence?`<button data-personal-open="${esc(item.id)}"><strong>${esc(item.title)}</strong><span>${esc(item.detail)}</span></button>`:`<div><strong>${esc(item.title)}</strong><span>${esc(item.detail)}</span></div>`}
function collectionMembershipControls(item,collections){let members=new Set(personalLearning()?.collectionIdsForItem?.(item.id)||[]),extra=collections.filter(collection=>!collection.system);if(!extra.length)return '';return `<details class="collection-assign"><summary>Collections</summary><div>${extra.map(collection=>`<button class="collection-membership ${members.has(collection.id)?'active':''}" data-collection-membership='${esc(JSON.stringify({collectionId:collection.id,itemId:item.id,enabled:!members.has(collection.id)}))}'>${members.has(collection.id)?'✓ ':''}${esc(collection.title)}</button>`).join('')}</div></details>`}
async function openPersonalItem(itemId){let item=saved.find(candidate=>candidate.id===itemId||notebookItemId(candidate)===itemId);if(!item)return;if(item.targetObjectId){await hydrateObjects([item.targetObjectId]);let target=byId.get(item.targetObjectId);if(target){go(routeForObject(target));return}}if(item.sourceContext?.sentence)go({type:'sentence',text:item.sourceContext.sentence})}
const notebookItemId=item=>item.id||savedTargetKey(item);
const shuffledNotebookIds=items=>items.map(notebookItemId).sort(()=>Math.random()-.5);
function orderedNotebookItems(items,order=[]){let byNotebookId=new Map(items.map(item=>[notebookItemId(item),item])),ordered=order.map(id=>byNotebookId.get(id)).filter(Boolean),known=new Set(ordered.map(notebookItemId));return [...ordered,...items.filter(item=>!known.has(notebookItemId(item)))]}
function notebookList(items,collections){return `<div class="saved-list notebook-list">${items.map(item=>`<article class="saved-item"><div class="saved-item-main">${personalItemOpenControl(item)}<small>${esc(item.targetType.replace(/_/g,' '))}${item.reviewCount?` · revisited ${item.reviewCount} time${item.reviewCount===1?'':'s'}`:''}</small></div><div class="saved-item-actions">${collectionMembershipControls(item,collections)}<button class="icon" aria-label="Remove ${esc(item.title)} from notebook" data-remove="${esc(savedTargetKey(item))}">×</button></div></article>`).join('')}</div>`}
function notebookCard(items,index){let item=items[index];if(!item)return '';let position=`${index+1} of ${items.length}`;return `<section class="notebook-card" aria-label="Notebook item ${position}"><div class="notebook-card-meta"><span>${esc(item.targetType.replace(/_/g,' '))}</span><span>${position}</span></div><div class="notebook-card-body"><h2>${esc(item.title)}</h2>${item.detail?`<p>${esc(item.detail)}</p>`:''}${item.sourceContext?.connection?`<small>${esc(item.sourceContext.connection)}</small>`:''}</div><div class="notebook-card-actions"><button class="secondary" data-notebook-prev ${index===0?'disabled':''}>← Previous</button><button class="primary" data-personal-open="${esc(item.id)}">Open original object →</button><button class="secondary" data-notebook-next ${index===items.length-1?'disabled':''}>Next →</button></div><button class="notebook-remove" data-remove="${esc(savedTargetKey(item))}">Remove from notebook</button></section>`}
vocabulary=function(v={}){let store=personalLearning(),collections=store?.listCollections?.()||[],activeCollectionId=v.collectionId||view.collectionId||store?.savedCollectionId||'system:saved',activeCollection=collections.find(collection=>collection.id===activeCollectionId)||collections[0],rawItems=activeCollection?personalItemsForCollection(activeCollection.id):saved,mode=v.mode||view.notebookMode||'list',items=orderedNotebookItems(rawItems,v.order||view.notebookOrder||[]),index=Math.min(Math.max(Number(v.index??view.notebookIndex??0),0),Math.max(items.length-1,0)),order=items.map(notebookItemId);view={type:'vocab',collectionId:activeCollection?.id||activeCollectionId,newCollection:Boolean(v.newCollection),notebookMode:mode,notebookIndex:index,notebookOrder:order};let controls=items.length?`<div class="notebook-controls"><div class="notebook-mode" role="group" aria-label="Notebook view"><button class="${mode==='list'?'active':''}" data-notebook-mode="list">List</button><button class="${mode==='card'?'active':''}" data-notebook-mode="card">Cards</button></div><button class="notebook-shuffle" data-notebook-shuffle ${items.length<2?'disabled':''}>Shuffle</button></div>`:'';shell(`<section class="page personal-library notebook"><div class="collection-header"><div class="type">Your learning</div><h1>${esc(activeCollection?.title||'Saved')}</h1><p class="section-copy">A quiet notebook for the connections you want to return to.</p></div><div class="collection-strip">${collections.map(collection=>`<button class="collection-chip ${collection.id===activeCollection?.id?'active':''}" data-collection="${esc(collection.id)}">${esc(collection.title)} <small>${personalItemsForCollection(collection.id).length}</small></button>`).join('')}<button class="collection-new" data-new-collection>＋ New collection</button></div>${v.newCollection?`<form class="new-collection" id="new-collection"><input aria-label="Collection name" maxlength="60" placeholder="For example: Travel French" autofocus/><button class="primary">Create</button><button type="button" class="secondary" data-cancel-collection>Cancel</button></form>`:''}${controls}${items.length?(mode==='card'?notebookCard(items,index):notebookList(items,collections)):`<div class="empty">Nothing is in ${esc(activeCollection?.title||'this collection')} yet. Save a word, meaning, form, sentence, expression, or grammar connection while you explore.</div>`}</section>`) }

function reviewPrompt(item){let type=item.targetType||'language_object',context=item.sourceContext||{},prompt='Reconnect this learning object',answer=item.detail||'Open this connection again in Liens.',connection=context.connection||'';if(type==='lexical_sense'){prompt='Which meaning were you learning?';connection=connection||'Return to the word to compare its other meanings.'}else if(type==='inflected_form'){prompt='Which verb and form does this connect to?';connection=connection||'Open the form to revisit its lemma and conjugation.'}else if(['grammar','grammar_construction'].includes(type)){prompt='What does this grammar connection help you notice?';connection=connection||'Explore its related forms and examples.'}else if(['expression','collocation','idiom'].includes(type)){prompt='How does this expression work as one unit?';connection=connection||'Explore its components and connected examples.'}else if(['sentence','learner_sentence'].includes(type)){prompt='Read this sentence, then reconnect its meaning and structure.';connection=connection||'Open it again to explore the words, forms, and grammar it contains.'}return {prompt,answer,connection}}
function reviewPage(v){let queue=(v.queueIds||personalLearning()?.todayItems?.().map(item=>item.id)||[]).map(id=>saved.find(item=>item.id===id)).filter(Boolean),index=Number(v.index||0),item=queue[index];view={type:'review',queueIds:queue.map(entry=>entry.id),index,revealed:Boolean(v.revealed),completed:Number(v.completed||0)};if(!item){shell(`<section class="page review"><button class="back" data-back>← Back</button><div class="type">Today’s Review</div><h1 class="sentence-title">A calm return</h1><div class="empty">${view.completed?'You have revisited every connection in this session.':'Save a connection while exploring, and it will appear here when it is ready to revisit.'}</div></section>`);return}let card=reviewPrompt(item);shell(`<section class="page review"><button class="back" data-back>← Back</button><div class="review-progress">${index+1} of ${queue.length} · ${view.completed} revisited</div><article class="review-card"><div class="prompt">${esc(card.prompt)}</div><h2>${esc(item.title)}</h2><p class="answer ${view.revealed?'show':''}">${esc(card.answer)}</p>${view.revealed&&card.connection?`<p class="review-connection">${esc(card.connection)}</p>`:''}</article>${view.revealed?`<div class="review-actions"><button class="secondary" data-review-grade="again">Again</button><button class="primary" data-review-grade="good">Good</button><button class="secondary" data-review-grade="easy">Easy</button></div>`:`<div class="review-actions"><button class="primary" data-review-reveal>Show connection</button></div>`}<button class="review-open" data-personal-open="${esc(item.id)}">Open in Liens →</button></section>`) }
function startReview(){let queue=personalLearning()?.todayItems?.().map(item=>item.id)||[];go({type:'review',queueIds:queue,index:0,revealed:false,completed:0})}
async function gradeReview(response){let itemId=view.queueIds?.[view.index];if(!itemId)return;await personalLearning()?.recordReview?.({itemId,response,promptType:'connection_recall'});refreshSaved();renderTarget({...view,index:view.index+1,revealed:false,completed:view.completed+1})}
const renderTargetForLearning=renderTarget;renderTarget=function(next){if(next.type==='review'){reviewPage(next);return}renderTargetForLearning(next)}
const renderForLearning=render;render=function(){if(view.type==='review')return reviewPage(view);return renderForLearning()}
const sentencePageForLearning=sentencePageIntegrated;sentencePageIntegrated=function(next){let personalItems=saved;saved=personalItems.map(item=>({...item,id:item.targetObjectId||item.id}));try{return sentencePageForLearning(next)}finally{saved=personalItems}}
function sentenceSavePayload(){let analysis=view.analysis;if(!analysis)return null;let localSentence=(byForm.get(norm(analysis.sentence))||[]).find(item=>item.type_code==='sentence'),translation=primaryEnglishGloss(localSentence)||learningAssist()?.get(sentenceLearningRequest(analysis))?.translation||'',objectIds=[...(analysis.formAnalyses||[]).map(item=>item.objectId),...(analysis.grammar||[]).map(item=>item.objectId),...(analysis.expressions||[]).map(item=>item.objectId)].filter(Boolean);return {targetKey:`sentence:${norm(analysis.sentence)}`,targetType:localSentence?'sentence':'learner_sentence',targetObjectId:localSentence?.id||null,title:analysis.sentence,detail:translation||'Sentence saved for local exploration.',sourceContext:{sentence:analysis.sentence,recognisedObjectIds:objectIds,connection:'Return to this sentence to explore its resolved words, forms, expressions, and grammar.'}}}
function decorateSentenceSave(){if(view.type!=='sentence')return;let title=document.querySelector('.sentence-title'),payload=sentenceSavePayload();if(!title||!payload||document.querySelector('[data-save-sentence]'))return;title.insertAdjacentHTML('afterend',`<button class="save sentence-save ${isSaved(payload.targetKey)?'saved':''}" data-save-sentence> ${isSaved(payload.targetKey)?'Saved sentence':'＋ Save sentence'} </button>`);let button=document.querySelector('[data-save-sentence]');if(button)button.onclick=()=>toggle(payload)}
const renderShellForLearning=shell;shell=function(content){renderShellForLearning(content);decorateSentenceSave()}
const bindForLearning=bind;bind=function(){bindForLearning();document.querySelectorAll('[data-personal-open]').forEach(button=>button.onclick=()=>openPersonalItem(button.dataset.personalOpen));document.querySelectorAll('[data-review-start]').forEach(button=>button.onclick=startReview);document.querySelectorAll('[data-review-reveal]').forEach(button=>button.onclick=()=>renderTarget({...view,revealed:true}));document.querySelectorAll('[data-review-grade]').forEach(button=>button.onclick=()=>gradeReview(button.dataset.reviewGrade));document.querySelectorAll('[data-collection]').forEach(button=>button.onclick=()=>vocabulary({collectionId:button.dataset.collection,mode:view.notebookMode||'list'}));document.querySelectorAll('[data-notebook-mode]').forEach(button=>button.onclick=()=>vocabulary({collectionId:view.collectionId,mode:button.dataset.notebookMode,order:view.notebookOrder,index:0}));document.querySelectorAll('[data-notebook-shuffle]').forEach(button=>button.onclick=()=>{let items=personalItemsForCollection(view.collectionId);vocabulary({collectionId:view.collectionId,mode:view.notebookMode||'list',order:shuffledNotebookIds(items),index:0})});document.querySelectorAll('[data-notebook-prev]').forEach(button=>button.onclick=()=>vocabulary({collectionId:view.collectionId,mode:'card',order:view.notebookOrder,index:view.notebookIndex-1}));document.querySelectorAll('[data-notebook-next]').forEach(button=>button.onclick=()=>vocabulary({collectionId:view.collectionId,mode:'card',order:view.notebookOrder,index:view.notebookIndex+1}));document.querySelectorAll('[data-new-collection]').forEach(button=>button.onclick=()=>vocabulary({...view,newCollection:true}));document.querySelectorAll('[data-cancel-collection]').forEach(button=>button.onclick=()=>vocabulary({...view,newCollection:false}));let form=document.querySelector('#new-collection');if(form)form.onsubmit=async event=>{event.preventDefault();let input=form.querySelector('input'),collection=await personalLearning()?.createCollection?.({title:input.value});if(collection)vocabulary({collectionId:collection.id,mode:view.notebookMode||'list'})};document.querySelectorAll('[data-collection-membership]').forEach(button=>button.onclick=async()=>{let change=JSON.parse(button.dataset.collectionMembership);await personalLearning()?.setCollectionMembership?.(change);vocabulary({collectionId:view.collectionId,mode:view.notebookMode,order:view.notebookOrder,index:view.notebookIndex})});document.querySelectorAll('[data-remove]').forEach(button=>button.onclick=async()=>{let key=button.dataset.remove,store=personalLearning();if(store)await store.removeByTargetKey(key);else{saved=saved.filter(item=>savedTargetKey(item)!==key);localStorage.setItem('liens-saved',JSON.stringify(saved))}refreshSaved();vocabulary({collectionId:view.collectionId,mode:view.notebookMode,order:view.notebookOrder,index:view.notebookIndex})})}
